import { expect, type Page } from "@playwright/test";

import { LLM_TIMEOUT } from "@e2e/config";

export const getLocators = (page: Page) => {
  const section = page.getByTestId("skill-section");
  const blockCanvas = page.getByTestId("skill-block-canvas").first();

  return {
    // Three view-header instances exist (chat, skill, history); the skill one is
    // the only header that reads "Active skill:".
    header: page.getByTestId("inspector-view-header").filter({ hasText: "Active skill:" }),
    section,
    blockCanvas,
    blockCard: page.getByTestId("skill-block-card"),
    activeBlockCard: page.locator('[data-testid="skill-block-card"][data-status="active"]'),
    blockSteps: blockCanvas.getByTestId("node").or(blockCanvas.getByTestId("node-selected")),
  };
};

const readActiveSkillName = async (
  locators: ReturnType<typeof getLocators>,
  timeout: number,
): Promise<string> => {
  const header = await locators.header.innerText({ timeout });
  return header.replace(/^\s*Active skill:\s*/, "").trim();
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    skillDocumentIsVisible: async (timeout = LLM_TIMEOUT) => {
      await expect(
        locators.section,
        "Skill document (skill-section) should render once a skill is active",
      ).toBeVisible({ timeout });
    },
    activeSkillNameIs: async (expected: string, timeout = LLM_TIMEOUT) => {
      await expect
        .poll(async () => await readActiveSkillName(locators, timeout), {
          message: `Skill pane header should read "Active skill: ${expected}"`,
          timeout,
        })
        .toBe(expected);
    },
    // Gap-tolerant variant: waits for the "Active skill:" header naming `expected`
    // to appear, tolerating a transient window where no skill is active (e.g. after
    // a restart, while the welcome skill re-activates). Unlike activeSkillNameIs it
    // never blocks on reading an absent header.
    skillHeaderShows: async (expected: string, timeout = LLM_TIMEOUT) => {
      await expect(
        locators.header.filter({ hasText: expected }),
        `Skill pane should show "Active skill: ${expected}"`,
      ).toBeVisible({ timeout });
    },
    skillHeaderIsOneOf: async (expectedNames: string[], timeout = LLM_TIMEOUT) => {
      await expect
        .poll(async () => await readActiveSkillName(locators, timeout), {
          message: `Skill pane header should be one of: ${expectedNames.join(", ")}`,
          timeout,
        })
        .toMatch(
          new RegExp(
            `^(${expectedNames.map((name) => name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})$`,
          ),
        );
    },
    blockCanvasIsVisible: async () => {
      await expect(
        locators.blockCard.first(),
        "The skill document should render its ordered blocks as cards",
      ).toBeVisible();
      await expect(
        locators.blockCanvas,
        "An ordered-block canvas should render in the skill document",
      ).toBeVisible();
    },
    activeBlockIsExpanded: async () => {
      await expect(
        locators.activeBlockCard,
        "The block running the active flow should be marked active",
      ).toBeVisible();
      await expect(
        locators.activeBlockCard,
        "The active block should expand its canvas by default",
      ).toHaveAttribute("data-expanded", "true");
    },
    blockStepCountAtLeast: async (count: number) => {
      await expect
        .poll(async () => await locators.blockSteps.count(), {
          message: `The ordered-block canvas should render at least ${count} step nodes`,
        })
        .toBeGreaterThanOrEqual(count);
    },
  };
};
